corrected_code:
import express from 'express';
import { Database } from 'bun:sqlite';
import { authenticateDeveloper } from '../auth.js';

const app = express();
const db = new Database('./data/dev_portal.sqlite');

app.get('/api/developer/api-keys/:keyId', authenticateDeveloper, (req, res) => {
  const { keyId } = req.params;

  // Restrict key query strictly to the authenticated developer's ownership
  const stmt = db.query(`
    SELECT id, name, key_prefix, scopes, rate_limit, created_at, developer_id
    FROM api_keys
    WHERE id = ? AND developer_id = ?
  `);

  const apiKey = stmt.get(keyId, req.developer.id);
  if (!apiKey) {
    return res.status(404).json({ error: 'API key not found or access denied' });
  }

  res.json({ apiKey });
});

export default app;
